import Foundation

// Zusätzliche Sprach-Overlays für Loc (pt/ja/zh/ru/id). In eine EIGENE Datei ausgelagert,
// damit der Release-Optimizer nicht an einem einzigen Riesen-Literal minutenlang kaut
// (gleicher Grund wie das _t1/_t2/_t3-Split in Loc.swift). Fallback je Key: Englisch
// (siehe Loc.t). Referenziert aus Loc.t als ptOverlay/jaOverlay/zhOverlay/ruOverlay/idOverlay.

// Portugiesisch-Overlay (532 Keys). Fallback: Englisch.
// In 10 Bloecke zerlegt: EIN Literal mit 543 Eintraegen ist fuer den
// Swift-Type-Checker EIN Ausdruck, dessen Kosten ueberproportional wachsen (der Build hing
// minutenlang genau in dieser Datei). Zusammengefuehrt beim ersten Zugriff.
let ptOverlay: [String: String] = {
    var d: [String: String] = [:]
    for p in [_ptOverlayP1, _ptOverlayP2, _ptOverlayP3, _ptOverlayP4, _ptOverlayP5, _ptOverlayP6, _ptOverlayP7, _ptOverlayP8, _ptOverlayP9, _ptOverlayP10, _ptOverlayP11] { d.merge(p) { a, _ in a } }
    return d
}()

