    "guide.pair.relink": "「連携アカウント」でウォッチを切断すると、次にサーバーに到達したときにウォッチ自身がペアリングを解除します — 「接続済み」の代わりに再びコードを表示します。既存のペアリングを上書きするには（別のウォッチ／アカウント）：ウォッチで「接続」→ ENTER でいつでも新しいコードを生成できます。ここで新しいコードを引き換えるまで古いトークンは有効なままなので、中断した試行は何も変えません。",
