    "guide.g.s1b": "して、次でコピーします：",
    "guide.g.s1c": "コピー先のフォルダ：",
    "guide.g.s1d": "ウォッチ上の。",
    "guide.g.s2Title": "2. ウォッチでコードを生成：",
