    "guide.g.s3Title": "3. ここにコードを入力：",
    "guide.g.s3": "→「ウォッチのコードを入力」。完了 — ウォッチがアカウントに連携されました。",
    "guide.g.s4Title": "4. データフィールドとアラーム：",
