    "guide.sync.retryTitle": "その直後：",
    "guide.sync.retry": "すぐに成功しない場合、ウォッチは自動で再試行します — ただし Pumpfoil アプリがウォッチで開いている間だけです。",
    "guide.sync.laterTitle": "あとで：",
