    "guide.pair.title": "Hubungkan jammu ke akunmu",
    "guide.pair.intro": "Kamu bisa merekam tanpa menghubungkan — sesi disimpan lokal dan terunggah otomatis nanti. Untuk mengaitkannya ke akunmu, ada dua cara:",
    "guide.pair.autoTitle": "Otomatis (Apple Watch & Wear OS):",
    "guide.pair.auto": "Pasang aplikasi di ponselmu dan masuk — selesai. Aplikasi jam mendapat koneksi otomatis lewat ponsel yang dipasangkan, tanpa kode. Jika jam menampilkan “Tautan tidak valid”, ketuk “Hubungkan ulang” — aplikasi mengambil token baru otomatis.",
    "guide.pair.codeTitle": "Dengan kode (Garmin & sebagai cadangan):",
    "guide.pair.code": "Di jam: “Hubungkan” → “Buat kode pairing”, lalu masukkan kode 6 digit di sini:",
    "guide.pair.relinkTitle": "Ganti atau putuskan (Garmin):",
    "guide.pair.relink": "Jika kamu memutuskan jam di “Akun tertaut”, jam melepaskan pairing dengan sendirinya saat berikutnya mencapai server — alih-alih “Terhubung” jam menampilkan kode lagi. Untuk menimpa pairing yang ada (jam/akun berbeda): di jam “Hubungkan” → ENTER membuat kode baru kapan saja. Token lama tetap aktif sampai kamu menukar kode baru di sini, jadi percobaan yang dibatalkan tidak mengubah apa pun.",
    "guide.pair.note": "Masuk dengan email, Google atau Apple — email yang sama berarti akun yang sama, tanpa penautan terpisah.",
