    "guide.g.manualLead": "Atau pasang manual dengan sideload (mis. untuk build pratinjau):",
    "guide.g.s1Title": "1. Pasang aplikasi:",
    "guide.g.s1a": "dapatkan “Pumpfoil” dari Connect IQ Store — atau .prg untuk modelmu",
    "guide.g.s1Download": "unduh di sini",
