// Norwegisch-Overlay (Bokmål; aus web/src/i18n/locales/nb.ts + app-eigene Keys aus dem
// Englischen). Anlass: erster norwegischer Nutzer (Sogndal, 05.08.2026); nn/no landen
// ebenfalls hier. In Bloecke zerlegt wie die anderen Overlays — EIN Riesen-Literal laesst
// den Swift-Type-Checker im Release-Build minutenlang kauen.
let nbOverlay: [String: String] = {
    var d: [String: String] = [:]
    for p in [_nbOverlayP1, _nbOverlayP2, _nbOverlayP3, _nbOverlayP4, _nbOverlayP5, _nbOverlayP6, _nbOverlayP7, _nbOverlayP8, _nbOverlayP9, _nbOverlayP10, _nbOverlayP11] { d.merge(p) { a, _ in a } }
    return d
}()

